//! The prompt string table (STRINGS.DAT). Built-in defaults are the stock
//! r5 strings; `strings.toml` overrides any of them by name.

use std::collections::HashMap;
use std::path::Path;

use anyhow::Context;

/// Stock strings, generated by `fluxbbs import` from a stock install.
const STOCK: &str = include_str!("../assets/strings.toml");

#[derive(Clone)]
pub struct Strings {
    map: HashMap<String, String>,
    stock: HashMap<String, String>,
}

/// r5 strings that were numbered before they had names; overrides
/// saved under the old names still apply.
fn renamed(old: &str) -> Option<&'static str> {
    let n: usize = old.strip_prefix('s')?.parse().ok()?;
    const NODE: [&str; 12] = [
        "MNCyouspeak", "MNCtheyspeak", "MNCenterchat", "MNCquitchat", "NodeAskNode", "NodeUserOn",
        "NodeMsgAskText", "NodeMsgSent", "NodeMsgReceived", "NodeBCaskText", "NodeBCsent", "NodeBCreceived",
    ];
    NODE.get(n.checked_sub(287)?).copied()
}

/// Every string's name, in the stock table's order (STRINGS.DAT's).
pub fn stock_names() -> Vec<&'static str> {
    STOCK.lines().filter_map(|l| l.split_once(" = ").map(|(n, _)| n.trim())).filter(|n| !n.starts_with('#')).collect()
}

impl Strings {
    pub fn load(path: &Path) -> anyhow::Result<Self> {
        let stock: HashMap<String, String> = toml::from_str(STOCK).context("built-in strings")?;
        let mut map = stock.clone();
        match std::fs::read_to_string(path) {
            Ok(s) => {
                let over: HashMap<String, String> =
                    toml::from_str(&s).with_context(|| format!("parsing {}", path.display()))?;
                map.extend(over.into_iter().map(|(k, v)| (renamed(&k).map_or(k, String::from), v)));
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => return Err(e).with_context(|| format!("reading {}", path.display())),
        }
        Ok(Self { map, stock })
    }

    pub fn set(&mut self, name: &str, text: String) {
        self.map.insert(name.to_string(), text);
    }

    /// The strings that differ from stock, in stock order (what
    /// strings.toml holds).
    pub fn overrides(&self) -> Vec<(String, String)> {
        let mut out: Vec<(String, String)> = stock_names()
            .into_iter()
            .filter_map(|n| self.map.get(n).filter(|v| self.stock.get(n) != Some(*v)).map(|v| (n.to_string(), v.clone())))
            .collect();
        // Names this build doesn't know (another version's) stay, after.
        let mut unknown: Vec<(String, String)> =
            self.map.iter().filter(|(k, _)| !self.stock.contains_key(*k)).map(|(k, v)| (k.clone(), v.clone())).collect();
        unknown.sort();
        out.extend(unknown);
        out
    }

    /// `mStr`: a string by its original name (`strPause` -> `"Pause"`).
    pub fn get(&self, name: &str) -> &str {
        debug_assert!(self.map.contains_key(name), "unknown string {name}");
        self.map.get(name).map_or("", String::as_str)
    }

    /// The built-in text of a string.
    pub fn stock(&self, name: &str) -> &str {
        self.stock.get(name).map_or("", String::as_str)
    }

    /// Has the SysOp changed this string from stock?
    pub fn changed(&self, name: &str) -> bool {
        self.map.get(name).map(String::as_str) != self.stock.get(name).map(String::as_str)
    }

    /// `strCode`: a string with `%S1`, `%S2`... replaced by `args`.
    pub fn fmt(&self, name: &str, args: &[&str]) -> String {
        // The values are data (often typed by a caller), not codes.
        let args: Vec<String> = args.iter().map(|a| fluxbbs_term::lit(a)).collect();
        substitute(self.get(name), &args.iter().map(String::as_str).collect::<Vec<_>>())
    }
}

/// `%S1`, `%s2`... in `s` replaced by `args`, in one pass: what's put in
/// is never read again, so a value that holds a tag itself (a subject of
/// `%s2`) stays as it is. Replacing tag by tag put the next value inside
/// that one, marks and all, and its [`fluxbbs_term::lit`] section ended
/// early: the rest of a caller's text ran as codes.
pub fn substitute(s: &str, args: &[&str]) -> String {
    let b = s.as_bytes();
    let mut out = String::with_capacity(s.len());
    let (mut i, mut from) = (0, 0);
    while i < b.len() {
        if b[i] == b'%' && matches!(b.get(i + 1), Some(b'S' | b's')) && b.get(i + 2).is_some_and(|d| (b'1'..=b'9').contains(d)) {
            // The longest number that names an argument.
            let digits = b[i + 2..].iter().take(2).take_while(|d| d.is_ascii_digit()).count();
            let hit = (1..=digits).rev().find_map(|n| {
                let k: usize = s[i + 2..i + 2 + n].parse().ok()?;
                (k <= args.len()).then_some((n, k))
            });
            if let Some((n, k)) = hit {
                out.push_str(&s[from..i]);
                out.push_str(args[k - 1]);
                i += 2 + n;
                from = i;
                continue;
            }
        }
        i += 1;
    }
    out.push_str(&s[from..]);
    out
}

/// Write a string table as TOML, one `Name = "text"` per line, in order.
pub fn to_toml(entries: &[(String, String)]) -> String {
    let mut out = String::from(
        "# flux/bbs prompt strings, from Iniquity's STRINGS.DAT. Names are the\n\
         # original str* constants; r5 additions without one are numbered.\n\n",
    );
    for (name, text) in entries {
        out.push_str(&format!("{name} = {}\n", toml::Value::String(text.clone())));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn unknown_names_are_kept() {
        let dir = std::env::temp_dir().join(format!("fluxbbs-strings-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("strings.toml");
        std::fs::write(&path, "FromANewerVersion = \"hi\"\n").unwrap();
        let s = Strings::load(&path).unwrap();
        assert_eq!(s.overrides(), [("FromANewerVersion".to_string(), "hi".to_string())]);
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn stock_strings_parse() {
        let s = Strings::load(Path::new("/nonexistent")).unwrap();
        assert!(s.get("Pause").contains("use"));
        assert!(s.fmt("InvalidMnuCmd", &["ZZ"]).contains("ZZ"));
    }

    #[test]
    fn changed_strings_remember_stock() {
        let mut s = Strings::load(Path::new("/nonexistent")).unwrap();
        let stock = s.get("Pause").to_string();
        assert!(!s.changed("Pause"));
        s.set("Pause", "wait".into());
        assert!(s.changed("Pause"));
        assert_eq!(s.stock("Pause"), stock);
        s.set("Pause", stock);
        assert!(!s.changed("Pause"));
    }

    #[test]
    fn names_and_overrides() {
        let names = stock_names();
        assert_eq!(names.first(), Some(&"DetectEmu"));
        let mut s = Strings::load(Path::new("/nonexistent")).unwrap();
        assert_eq!(names.len(), s.map.len(), "every stock string is listed");
        assert!(s.overrides().is_empty());
        s.set("Pause", "wait".into());
        assert_eq!(s.overrides(), [("Pause".to_string(), "wait".to_string())]);
    }

    #[test]
    fn old_numbered_names_still_apply() {
        assert_eq!(renamed("s295"), Some("NodeMsgReceived"));
        assert_eq!(renamed("s286"), None);
        assert_eq!(renamed("Pause"), None);
    }

    #[test]
    fn substitutes_both_cases() {
        assert_eq!(substitute("%S1 and %s2", &["a", "b"]), "a and b");
        assert_eq!(substitute("%S3%s0%S12 100%S", &["a", "b"]), "%S3%s0a2 100%S");
        let ten: Vec<String> = (1..=10).map(|n| format!("<{n}>")).collect();
        assert_eq!(substitute("%S10%s1", &ten.iter().map(String::as_str).collect::<Vec<_>>()), "<10><1>");
    }

    #[test]
    fn a_value_holding_a_tag_is_not_substituted_again() {
        use fluxbbs_term::{Source, Token, tokenize_str};
        assert_eq!(substitute("%S1 by %S2", &["x%s2%S1", "y%S1"]), "x%s2%S1 by y%S1");
        // A subject naming the next value's tag: its own codes stay text.
        let strings = Strings::load(Path::new("no-such-strings.toml")).unwrap();
        let s = strings.fmt("NewPostNotice", &["Area", "x%s2|CS|PA|DS@01%RN", "Someone"]);
        let got = tokenize_str(&s, Source::String);
        assert!(got.iter().all(|t| matches!(t, Token::Text(_)) || matches!(t, Token::Ctrl(c) if c.is_colour())), "{got:?}");
        let shown: Vec<u8> = got.iter().filter_map(|t| if let Token::Text(b) = t { Some(b.clone()) } else { None }).flatten().collect();
        assert!(String::from_utf8_lossy(&shown).contains("x%s2|CS|PA|DS@01%RN by Someone"), "{got:?}");
    }
}
